#pragma once
#include <QDate>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QMap>
#include <QRegularExpression>
#include <QThread>
#include <QTime>
#include <cmath>
#include <stdexcept>

namespace publicPriceDetail {
inline void need(bool ok,const QString&message){if(!ok)throw std::runtime_error(message.toUtf8().constData());}
inline void active(){need(!QThread::currentThread()->isInterruptionRequested(),"旧公开价格详情读取已取消");}
inline void keys(QJsonObject object,QStringList expected){expected.sort();need(object.keys()==expected,"旧价格详情字段与已审协议不符，未丢弃未知字段");}
inline bool date(QString value){return QRegularExpression("^\\d{4}-\\d{2}-\\d{2}$").match(value).hasMatch()&&QDate::fromString(value,Qt::ISODate).isValid();}
inline QString symbol(QString id){need(QRegularExpression("^(SH|SZ):stock:[0-9]{6}$").match(id).hasMatch(),"价格详情需要已核对的完整股票身份，不能按裸代码或指数猜测");return id.section(':',0,0).toLower()+id.section(':',2,2);}
inline int seconds(QString value){need(QRegularExpression("^(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d$").match(value).hasMatch(),"旧详情时间无效");auto time=QTime::fromString(value,"HH:mm:ss");return time.hour()*3600+time.minute()*60+time.second();}
inline QString phase(int at){return (at>=34200&&at<=41400)||(at>=46800&&at<53820)?"continuous":at>=33300&&at<34200?"opening-result":at>=53820&&at<=54005?"closing-result":"outside-session";}
inline QJsonArray assignment(QString text,QString name){need(text.size()<=1000000,"旧公开原响应超限，未截断");auto match=QRegularExpression("^"+QRegularExpression::escape(name)+"=(\\[[\\s\\S]*\\]);?$").match(text.trimmed());need(match.hasMatch(),"旧公开原响应证券/变量身份不符");QJsonParseError error;auto doc=QJsonDocument::fromJson(match.captured(1).toUtf8(),&error);auto result=doc.array();need(error.error==QJsonParseError::NoError&&doc.isArray()&&result.size()==2&&result[1].isString(),"旧公开原响应不是已审数组协议");return result;}
inline QJsonArray info(QString text,QString expectedSymbol,QString expectedDate){auto value=assignment(text,"v_detail_time_"+expectedSymbol);auto day=value[0].toVariant().toString();need(QRegularExpression("^\\d{8}$").match(day).hasMatch()&&day==expectedDate.sliced(0,4)+expectedDate.sliced(5,2)+expectedDate.sliced(8,2),"旧价格详情原索引日期不符");auto ranges=value[1].toString().split('|');need(!ranges.isEmpty()&&ranges.size()<=256,"旧价格详情页数超限或空");QJsonArray out;for(auto range:ranges){auto bounds=range.split('~');need(bounds.size()==2&&seconds(bounds[0])<=seconds(bounds[1]),"旧详情页时间边界无效");out.append(range);}return out;}
inline QJsonObject record(QString raw,QString tradingDate){auto f=raw.split('/');need(f.size()==7&&QRegularExpression("^\\d+$").match(f[0]).hasMatch(),"旧价格原记录字段不符");bool ok=false;double id=f[0].toDouble(&ok);need(ok&&id>=0&&id<=9007199254740991.0&&std::floor(id)==id,"旧价格序列身份无效");double price=f[2].toDouble(&ok);need(ok&&std::isfinite(price)&&price>0,"旧价格原值无效，未补零");int at=seconds(f[1]);return {{"id",id},{"time",tradingDate+" "+f[1]},{"price",price},{"phase",phase(at)},{"quantityRaw",f[4]},{"amountRaw",f[5]},{"sideRaw",f[6]},{"raw",raw}};}
inline QJsonObject validate(const QByteArray&raw,QString nativeId,QString tradingDate){
 active();need(raw.size()>0&&raw.size()<=8*1024*1024&&QString::fromUtf8(raw).toUtf8()==raw,"旧价格文件空/超限/UTF8损坏，未截断");need(date(tradingDate),"旧价格日期无效");const auto expectedSymbol=symbol(nativeId);QJsonParseError error;auto document=QJsonDocument::fromJson(raw,&error);need(error.error==QJsonParseError::NoError&&document.isObject(),"旧价格文件JSON损坏");auto s=document.object();keys(s,{"version","code","symbol","tradingDate","provider","fetchedAt","providerObservedAt","modalIntervalSeconds","paginationComplete","outsideSessionMissingRecords","rawInfoBefore","rawInfoAfter","rawPages","records"});
 need(s["version"]==1&&s["code"]==nativeId.section(':',2,2)&&s["symbol"]==expectedSymbol&&s["tradingDate"]==tradingDate&&s["provider"]=="tencent-public-detail","旧公开报价来源/证券/日期不一致");
 need(s["fetchedAt"].isString()&&!s["fetchedAt"].toString().isEmpty()&&s["providerObservedAt"].isString()&&s["paginationComplete"].isBool()&&s["rawInfoBefore"].isString()&&s["rawInfoAfter"].isString()&&s["rawPages"].isArray()&&s["records"].isArray(),"旧详情状态/时刻字段类型改变");
 need(s["modalIntervalSeconds"].isNull()||(s["modalIntervalSeconds"].isDouble()&&s["modalIntervalSeconds"].toDouble()>0&&s["modalIntervalSeconds"].toDouble()==s["modalIntervalSeconds"].toInt()),"旧观测精度无效，未猜测");
 const auto before=info(s["rawInfoBefore"].toString(),expectedSymbol,tradingDate);const auto after=info(s["rawInfoAfter"].toString(),expectedSymbol,tradingDate);const auto pages=s["rawPages"].toArray(),records=s["records"].toArray();need(!pages.isEmpty()&&pages.size()<=256&&before.size()==pages.size()&&after.size()>=pages.size()&&!records.isEmpty()&&records.size()<=17920,"旧详情原页/记录数不完整或超限");
 QJsonArray parsed;for(int index=0;index<pages.size();++index){active();auto p=pages[index].toObject();keys(p,{"index","range","text"});need(p["index"]==index&&p["range"].isString()&&p["text"].isString(),"旧详情页身份改变");auto page=assignment(p["text"].toString(),"v_detail_data_"+expectedSymbol);need(page[0]==index,"旧详情原页序号改变");auto rows=page[1].toString().split('|');need(!rows.isEmpty()&&rows.size()<=70,"旧详情原页记录数不符");QJsonArray part;for(auto value:rows)part.append(record(value,tradingDate));need(p["range"]==part[0].toObject()["time"].toString().mid(11)+"~"+part.last().toObject()["time"].toString().mid(11),"旧详情已捕获页范围与原响应不同");for(auto value:part)parsed.append(value);}
 need(parsed==records,"旧价格/量/方向/精度记录与完整原始页不同");double missing=0;for(int index=0;index<records.size();++index){active();auto r=records[index].toObject();double gap=r["id"].toDouble()-(index?records[index-1].toObject()["id"].toDouble()+1:0);bool outside=index&&records[index-1].toObject()["time"].toString().mid(11)>"15:00:05"&&r["time"].toString().mid(11)>"15:00:05";need(gap==0||(outside&&gap>0),"旧详情序列缺失/重复不符合原盘后缺口说明");need(!index||r["time"].toString()>=records[index-1].toObject()["time"].toString(),"旧详情时序倒置");missing+=gap;}
 need(s["outsideSessionMissingRecords"].isDouble()&&s["outsideSessionMissingRecords"].toDouble()==missing&&s["providerObservedAt"]==records.last().toObject()["time"],"旧详情缺口或最后来源时刻不一致");return s;
}
inline bool validVolume(QJsonObject row){bool ok=false;auto quantity=row["quantityRaw"].toString(),amount=row["amountRaw"].toString();double lots=quantity.toDouble(&ok);if(!ok||!QRegularExpression("^\\d+$").match(quantity).hasMatch()||!std::isfinite(lots)||std::floor(lots)!=lots||lots>9007199254740991.0/100)return false;double cash=amount.toDouble(&ok);return ok&&QRegularExpression("^\\d+(?:\\.\\d+)?$").match(amount).hasMatch()&&std::isfinite(cash);}
inline QJsonArray aggregate(const QJsonArray&records,int interval){
 need(interval==5||interval==30,"旧详情派生周期只支持5秒或30秒");bool validContinuous=true;int continuous=0;for(auto v:records){auto r=v.toObject();if(r["phase"]=="continuous"){++continuous;validContinuous=validContinuous&&validVolume(r);}}validContinuous=validContinuous&&continuous>0;QMap<QString,QJsonObject>bars;
 for(auto v:records){active();auto r=v.toObject();int at=seconds(r["time"].toString().mid(11));bool opening=r["phase"]=="opening-result"&&at>=33900&&at<=33905,closing=r["phase"]=="closing-result"&&at>=53820&&at<=54005;if(r["phase"]!="continuous"&&!opening&&!closing)continue;bool volume=r["phase"]=="continuous"?validContinuous:validVolume(r);int start=at<46800?34200:46800;int end=opening?33900:std::min(closing?54000:at<46800?41400:53820,start+std::max(interval,int(std::ceil(double(at-start)/interval))*interval));auto time=r["time"].toString().left(11)+QTime(end/3600,(end%3600)/60,end%60).toString("HH:mm:ss");auto bar=bars.value(time);double price=r["price"].toDouble();if(bar.isEmpty()){bar={{"time",time},{"open",price},{"high",price},{"low",price},{"price",price},{"volume",QJsonValue::Null},{"amount",QJsonValue::Null},{"averagePrice",QJsonValue::Null},{"observedCount",0},{"source","tencent-public-detail"},{"providerLastAt",r["time"]},{"phase",r["phase"]}};if(volume){bar["volume"]=0;bar["amount"]=0;bar["volumeSource"]="tencent-public-detail-derived";}}
  bar["high"]=std::max(bar["high"].toDouble(),price);bar["low"]=std::min(bar["low"].toDouble(),price);bar["price"]=price;bar["providerLastAt"]=r["time"];bar["observedCount"]=bar["observedCount"].toInt()+1;if(!volume){bar["volume"]=QJsonValue::Null;bar["amount"]=QJsonValue::Null;bar.remove("volumeSource");}else if(bar["volume"].isDouble()){bar["volume"]=bar["volume"].toDouble()+r["quantityRaw"].toString().toDouble()*100;bar["amount"]=bar["amount"].toDouble()+r["amountRaw"].toString().toDouble();}bars[time]=bar;
 }QJsonArray out;for(auto bar:bars)out.append(bar);return out;
}
}
